import{af as a,z as s,J as t,ab as o}from"./chunks/framework.B-hMd4P7.js";const u=JSON.parse('{"title":"Messages","description":"","frontmatter":{},"headers":[],"relativePath":"devices/api/messages/index.md","filePath":"devices/api/messages/index.md"}'),i={name:"devices/api/messages/index.md"};function r(d,e,n,l,c,p){return s(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792691745000"},[...e[0]||(e[0]=[o('<h1 id="messages" tabindex="-1">Messages <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;Messages&quot;">​</a></h1><p>Messages are the core building blocks of the protocol, allowing you to send and receive data and commands to and from devices.</p><p>All messages follow a common structure, but each type of message has its own specific purpose, payload, requirements and usage.</p><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><p>Messages all have a type, represented as a <code>uint16</code> value, which defines the structure and purpose of the message, including what headers and payload it may or should contain.</p><p>Some example message types for the device API include:</p><ul><li><a href="./13-heartbeat">13: Heartbeat</a> - A simple message to indicate the communication link is alive</li><li><a href="./34-device-status">34: Device Status</a> - A message containing various status information about the device</li><li><a href="./10008-base-page">10008: Base Page</a> - A message to draw a preset page on the device&#39;s display</li><li><a href="./10011-draw-element">10011: Draw Element</a> - A message to draw a shape on the device&#39;s display</li><li>...</li></ul><p>You can find complete documentation for the messages used as part of the device API in the sidebar of this page.</p><p>Values of <code>60,000</code> to <code>61,000</code> are currently reserved for custom use. Feel free to implement your own messages within this range.</p><h2 id="header-fields" tabindex="-1">Header fields <a class="header-anchor" href="#header-fields" aria-label="Permalink to &quot;Header fields&quot;">​</a></h2><p>Messages make use of a few common <a href="/docs/pr/23/devices/api/protocol/headers">header fields</a> that are defined at the protocol level that you&#39;ll likely want to familiarize yourself with as they are used in device messaging.</p><p>Such as:</p><ul><li><a href="./../protocol/headers#1-message-id">1: Message ID</a> for uniquely identifying messages</li><li><a href="./../protocol/headers#3-response-to">3: Response to</a> for linking responses to requests</li><li><a href="./../protocol/headers#4-status">4: Status</a> for indicating the status of a message</li><li><a href="./../protocol/headers#5-method">5: Method</a> for optionally specifying the action to be taken</li></ul><p>You can find the full list of header fields in the <a href="/docs/pr/23/devices/api/protocol/headers">Headers documentation</a> for the protocol.</p><h3 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h3><p>A method is an optional header field that can be included in messages, and is sometimes used throughout the device API.</p><p>Currently defined methods are:</p><ul><li><code>1: SET</code> - Set a value or state on the device</li><li><code>2: GET</code> - Get a value or state from the device</li><li><code>3: SUBSCRIBE</code> - Subscribe to updates for a value or state on the device</li><li><code>5: UNSUBSCRIBE</code> - Unsubscribe from updates for a value or state on the device</li></ul><p>You can find more information about these methods in the <a href="./../protocol/headers#5-method">MH 5: Method</a> section.</p><h2 id="communication-patterns" tabindex="-1">Communication patterns <a class="header-anchor" href="#communication-patterns" aria-label="Permalink to &quot;Communication patterns&quot;">​</a></h2><p>A request can receive a typed response or an <a href="./5-ack">ACK (MT5)</a>. The operation reference defines its expected reply, payload and errors; later subscription publications are separate events.</p><p>See <a href="./../protocol/responses">Responses and acknowledgments</a> for Message ID/Response to correlation, Status, ACK suppression and message-format versions.</p>',22)])])}const m=a(i,[["render",r]]);export{u as __pageData,m as default};
